<?php $joined=$me && $a->categories->member((int)$circle['id'],(int)$me['id']); ?>
<div class="breadcrumb section"><a href="<?= e(url('circles')) ?>"><?= t('Circles') ?></a><?= icon('chevron') ?><span><?= e($circle['name']) ?></span></div>
<section class="circle-profile panel glass"><div class="circle-profile-icon"><?= icon($circle['icon']) ?></div><div class="grow"><span class="eyebrow">A SPACE TO BELONG</span><h1><?= e($circle['name']) ?></h1><p><?= e($circle['description']) ?></p><div class="row wrap"><span class="pill"><?= t('Reading') ?>: <?= t($circle['access_level']) ?></span><span class="pill"><?= t('Posting') ?>: <?= t($circle['post_level']) ?></span><?php if($joined): ?><span class="pill soft"><?= icon('check') ?><?= t('Joined') ?></span><?php endif ?></div></div><div class="circle-join"><strong class="purchase-price"><?= (int)$circle['join_amount']?e(price((int)$circle['join_amount'],$circle['join_currency'])):t('Free') ?></strong><p><?= (int)$circle['join_days']?(int)$circle['join_days'].' '.t('days'):t('Permanent membership') ?></p><?php if(!$joined && (int)$circle['join_open']): ?><?php if($me): ?><?= form_start('buy') . intent() . hidden('kind','circle') . hidden('item_id',$circle['id']) ?><?php button('Join circle','','plus'); ?></form><?php else: ?><a class="btn" href="<?= e(url('login')) ?>"><?= t('Sign in to join') ?></a><?php endif ?><?php elseif(!$joined): ?><span class="pill"><?= t('Joining paused') ?></span><?php endif ?></div></section>
<?php if(!$allowed): ?><section class="circle-locked panel"><span class="quick-icon"><?= icon('lock') ?></span><h2><?= t('The conversation continues inside.') ?></h2><p><?= t('Join this circle and meet its access requirements to read its posts. No post text or attachment is exposed here.') ?></p></section><?php else: ?><div class="section-heading section"><h2><?= t('Recent conversations') ?></h2><?php if($me && $a->categories->allowed((int)$circle['id'],$me,'post') && $s->enabled('submissions')): ?><a class="btn" href="<?= e(url('write',['kind'=>'thread','category'=>$circle['id']])) ?>"><?= icon('plus') ?><?= t('Start a conversation') ?></a><?php endif ?></div><div class="thread-list panel glass"><?php foreach($feed['items'] as $entry){partial('thread',['entry'=>$entry]);}if(!$feed['items']){empty_state('Be the first to start a conversation.','message');} ?></div><?php partial('pagination',['feed'=>$feed,'route'=>'circle']); ?><?php endif ?>
